<?php
/** 实例绑定的发布前只读盘点，不启动应用，不输出凭据或业务内容。 */
$site=$argv[1]??'';$sites=['rh'=>['rh.cc3798.com','ruihao','3306'],'008'=>['008.cc3798.com','mohe_008','3307'],'010'=>['010.cc3798.com','mohe_010_app','3307']];if(!isset($sites[$site]))throw new RuntimeException('EXPLICIT_INSTANCE_REQUIRED');
[$domain,$dbName,$port]=$sites[$site];$root='/www/wwwroot/'.$domain;$env=parse_ini_file($root.'/.env',true,INI_SCANNER_RAW);$cfg=array_change_key_case($env['DATABASE']??$env['database']??[]);if($cfg['database']!==$dbName||(string)$cfg['hostport']!==$port||$cfg['prefix']!=='eb_')throw new RuntimeException('INSTANCE_DATABASE_MISMATCH');
$out=['site'=>$site,'root'=>$root,'database'=>$dbName,'port'=>$port,'backend'=>[],'frontends'=>[],'protected'=>[]];
foreach(['app','route','config'] as $directory){$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root.'/'.$directory,FilesystemIterator::SKIP_DOTS));foreach($it as $file)if($file->isFile())$out['backend'][substr($file->getPathname(),strlen($root)+1)]=hash_file('sha256',$file->getPathname());}ksort($out['backend']);
foreach(['.env','public/index.html','public/view_mobile_v3/index.html','public/view_fund_v3/index.html','public/view_inventory_v3/index.html'] as $f)$out['protected'][$f]=is_file($root.'/'.$f)?hash_file('sha256',$root.'/'.$f):null;
$roots=[$root];if($site==='rh')$roots[]=$root.'-8080';foreach($roots as $frontRoot){foreach(['cashier'=>'public/view_cashier_v3/index.html','admin'=>'public/system.html'] as $kind=>$entry){if(!is_file($frontRoot.'/'.$entry))continue;$html=file_get_contents($frontRoot.'/'.$entry);preg_match_all('~(?:src|href)=["\']?([^"\'\s>]+\.(?:js|css)(?:\?[^"\'\s>]*)?)~',$html,$m);$assets=[];foreach($m[1] as $url){$p=parse_url($url,PHP_URL_PATH);if(parse_url($url,PHP_URL_SCHEME))continue;$p=preg_replace('~^/preview-8080/~','/',$p);$full=$frontRoot.'/public/'.ltrim($p,'/');if(is_file($full))$assets[$p]=hash_file('sha256',$full);} $out['frontends'][]=['root'=>$frontRoot,'kind'=>$kind,'entry'=>$entry,'sha256'=>hash('sha256',$html),'assets'=>$assets];}}
$db=new PDO('mysql:host='.$cfg['hostname'].';port='.$port.';dbname='.$dbName.';charset=utf8mb4',$cfg['username'],$cfg['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$db->exec('SET TRANSACTION READ ONLY');$db->beginTransaction();try{$out['mysqlVersion']=$db->getAttribute(PDO::ATTR_SERVER_VERSION);$out['upgrades']=$db->query('SELECT upgrade_key,code_version,executed_at FROM eb_database_upgrade_log ORDER BY id DESC LIMIT 12')->fetchAll();$rows=$db->query("SELECT * FROM eb_job_position_channel_rule ORDER BY id")->fetchAll();$out['channelRules']=['rows'=>count($rows),'sha256'=>hash('sha256',json_encode($rows,JSON_UNESCAPED_UNICODE))];$out['r28Tables']=$db->query("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('eb_store_v3_permission_catalog','eb_store_v3_permission_audit')")->fetchAll();}finally{$db->rollBack();}echo json_encode($out,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),PHP_EOL;
